class Solution:
    def profitableSchemes(self, n: int, minProfit: int, group: list[int], profit: list[int]) -> int:
        MOD = 1000000007
        ans = 0
        def dfs(i: int, members: int, gain: int) -> None:
            nonlocal ans
            if members > n:
                return
            if i == len(group):
                if gain >= minProfit:
                    ans = (ans + 1) % MOD
                return
            dfs(i + 1, members, gain)
            dfs(i + 1, members + group[i], gain + profit[i])
        dfs(0, 0, 0)
        return ans

